(()=>{'use strict';
const init=()=>{const host=document.querySelector('[data-elementor-id="8134"]');const catalog=host?.querySelector('.fc-catalog');if(!catalog||catalog.dataset.fcPlatformReady||document.body.classList.contains('elementor-editor-active'))return;catalog.dataset.fcPlatformReady='true';
const cards=[...catalog.querySelectorAll('.fc-card')], search=catalog.querySelector('[data-fc-search]'), genres=[...catalog.querySelectorAll('[data-fc-filter]')],platforms=[...catalog.querySelectorAll('[data-fc-platform]')],counter=catalog.querySelector('.fc-catalog-count .elementor-heading-title'),more=catalog.querySelector('.fc-loadmore'),empty=catalog.querySelector('.fc-empty'),reset=catalog.querySelector('[data-fc-reset]');
let genre='all',platform='all',limit=6;
const values=new Map(cards.map(card=>{const text=card.querySelector('.fc-platforms')?.textContent.toLowerCase()||'';const classes=[...card.querySelectorAll('.fc-platforms i,.fc-platforms svg')].map(n=>n.getAttribute('class')).join(' ');return[card,{title:(card.querySelector('.fc-card-title')?.textContent||'').toLowerCase(),platforms:new Set([/switch|nintendo/.test(text+classes)?'switch':'',/xbox/.test(text+classes)?'xbox':'',/playstation/.test(text+classes)?'playstation':'',/\bpc\b|desktop|steam|windows/.test(text+classes)?'pc':''].filter(Boolean))}]}));
const read=()=>{const p=new URL(location.href).searchParams;genre=genres.some(a=>a.dataset.fcFilter===p.get('genre'))?p.get('genre'):'all';platform=platforms.some(a=>a.dataset.fcPlatform===p.get('platform'))?p.get('platform'):'all';search.value=(p.get('q')||'').slice(0,100);limit=Math.max(6,Math.min(cards.length,Number(p.get('shown'))||6))};
const render=(save=true)=>{const q=search.value.trim().toLowerCase();let found=0;cards.forEach(card=>{const v=values.get(card);const matches=(genre==='all'||card.classList.contains('fc-category-'+genre))&&(platform==='all'||v.platforms.has(platform))&&v.title.includes(q);if(matches)found++;card.hidden=!matches||found>limit});counter.textContent=Math.min(found,limit)+' / '+found+' games';more.hidden=found<=limit;empty.hidden=!!found;empty.style.display=found?'none':'block';if(reset)reset.hidden=!q&&genre==='all'&&platform==='all';for(const a of genres){const active=a.dataset.fcFilter===genre;a.setAttribute('role','button');a.setAttribute('aria-pressed',String(active));a.closest('.fc-filter')?.classList.toggle('fc-current',active)}for(const a of platforms){const active=a.dataset.fcPlatform===platform;a.setAttribute('role','button');a.setAttribute('aria-pressed',String(active));a.closest('.fc-platform-filter')?.classList.toggle('fc-platform-current',active)}if(save){const u=new URL(location.href);for(const[k,v]of Object.entries({genre:genre==='all'?'':genre,platform:platform==='all'?'':platform,q:search.value.trim(),shown:limit>6?String(limit):''})){if(v)u.searchParams.set(k,v);else u.searchParams.delete(k)}history.replaceState(null,'',u)}catalog.dispatchEvent(new CustomEvent('fc:catalog-updated',{bubbles:true}))};
const intercept=e=>{const a=e.target.closest('[data-fc-filter],[data-fc-platform],.fc-loadmore a,[data-fc-reset]');if(!a)return;if(e.type==='keydown'&&![' ','Enter'].includes(e.key))return;e.preventDefault();e.stopImmediatePropagation();if(a.dataset.fcFilter){genre=a.dataset.fcFilter;limit=6}else if(a.dataset.fcPlatform){platform=a.dataset.fcPlatform;limit=6}else if(a.closest('.fc-loadmore'))limit+=6;else{genre=platform='all';search.value='';limit=6;search.focus()}render()};
catalog.addEventListener('click',intercept,true);catalog.addEventListener('keydown',intercept,true);catalog.addEventListener('input',e=>{if(e.target!==search)return;e.stopImmediatePropagation();limit=6;render()},true);window.addEventListener('popstate',()=>queueMicrotask(()=>{read();render(false)}));counter.setAttribute('role','status');counter.setAttribute('aria-live','polite');catalog.querySelector('.fc-platformbar')?.setAttribute('role','group');catalog.querySelector('.fc-platformbar')?.setAttribute('aria-label','Filter games by platform');read();queueMicrotask(()=>render(false));};if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init,{once:true});else init();})();